# 联想 AI 岗笔试三块的可跑对照模板（纯标准库，无第三方依赖）。
# 1) 编程题「贪心只过 18%」：零钱兑换，贪心 vs 完全背包 DP 对拍，
#    反例 coins=[1,3,4]、amount=6（贪心 3 枚，最优 2 枚）。
# 2) 选择题 HMM：Viterbi 解码（对数域，避免连乘下溢）。
# 3) 选择题 LoRA：增量 (alpha/r)·B@A 与可训练参数量对比。
# 直接运行本文件会跑完全部断言并打印结果。
import math

INF = float('inf')


def greedy_min_coins(coins, amount):
    '''贪心：每次取不超过余额的最大面值；币制不成链式倍数时会错。'''
    if amount < 0:
        raise ValueError('amount 必须非负')
    rest, used = amount, 0
    for c in sorted(coins, reverse=True):
        if c <= 0:
            raise ValueError('面值必须为正整数')
        used += rest // c
        rest %= c
    return used if rest == 0 else -1


def dp_min_coins(coins, amount):
    '''完全背包：dp[a] 是凑出金额 a 的最少硬币数，无解返回 -1。'''
    if amount < 0:
        raise ValueError('amount 必须非负')
    if any(c <= 0 for c in coins):
        raise ValueError('面值必须为正整数')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return -1 if dp[amount] == INF else dp[amount]


def viterbi(obs, states, start_p, trans_p, emit_p):
    '''HMM 解码：返回 (最优状态序列, 对数概率)，全程取 log 防下溢。'''
    if not obs:
        return [], 0.0
    lg = lambda p: math.log(p) if p > 0 else -INF
    dp = {s: lg(start_p[s]) + lg(emit_p[s][obs[0]]) for s in states}
    back = []
    for t in range(1, len(obs)):
        prev, cur = {}, {}
        for s in states:
            best_s, best_v = None, -INF
            for p in states:
                v = dp[p] + lg(trans_p[p][s])
                if v > best_v:
                    best_s, best_v = p, v
            prev[s] = best_s
            cur[s] = best_v + lg(emit_p[s][obs[t]])
        back.append(prev)
        dp = cur
    last = max(states, key=lambda s: dp[s])
    path = [last]
    for prev in reversed(back):
        path.append(prev[path[-1]])
    path.reverse()
    return path, dp[last]


def lora_delta(w, a, b, alpha, r):
    '''LoRA 前向：W' = W + (alpha/r) * B @ A，A 是 [r,k]、B 是 [d,r]。'''
    if r <= 0 or alpha <= 0:
        raise ValueError('r 与 alpha 必须为正')
    d, k = len(w), len(w[0])
    if len(a) != r or len(a[0]) != k or len(b) != d or len(b[0]) != r:
        raise ValueError('形状必须是 A[r,k]、B[d,r]')
    scale = alpha / r
    return [[w[i][j] + scale * sum(b[i][t] * a[t][j] for t in range(r))
             for j in range(k)] for i in range(d)]


def _self_test():
    # 1) 贪心失效的形状：小样例过、全局最优挂
    assert greedy_min_coins([1, 3, 4], 6) == 3
    assert dp_min_coins([1, 3, 4], 6) == 2
    # 规范币制（每个面值都是前面面值的倍数）下贪心才等于最优
    canonical = [1, 5, 10, 50]
    for amount in range(0, 61):
        assert greedy_min_coins(canonical, amount) == dp_min_coins(canonical, amount)
    # 边界：无解、金额 0、面值非法
    assert dp_min_coins([3, 5], 1) == -1 and dp_min_coins([3, 5], 0) == 0
    for bad in ([0], [-1, 2]):
        try:
            dp_min_coins(bad, 4)
            raise AssertionError('非法面值没有被拦下')
        except ValueError:
            pass
    # 2) HMM：观测 [a, b] 下最优状态序列应为 ['H', 'L']
    states = ['H', 'L']
    start = {'H': 0.6, 'L': 0.4}
    trans = {'H': {'H': 0.7, 'L': 0.3}, 'L': {'H': 0.4, 'L': 0.6}}
    emit = {'H': {'a': 0.9, 'b': 0.1}, 'L': {'a': 0.2, 'b': 0.8}}
    path, score = viterbi(['a', 'b'], states, start, trans, emit)
    assert path == ['H', 'L'] and score < 0
    assert viterbi([], states, start, trans, emit) == ([], 0.0)
    # 3) LoRA：alpha/r 缩放、B 零初始化让起点等于原模型、参数量对比
    w = [[1.0, 0.0], [0.0, 1.0]]
    got = lora_delta(w, [[1.0, 0.0]], [[2.0], [3.0]], alpha=2, r=1)
    assert got == [[5.0, 0.0], [6.0, 1.0]]
    assert lora_delta([[7.0]], [[1.0]], [[0.0]], alpha=8, r=1) == [[7.0]]
    d = k = 4096
    rr = 8
    assert rr * k + d * rr == 65536 and d * k == 256 * (rr * k + d * rr)
    print('贪心 coins=[1,3,4] amount=6 ->', greedy_min_coins([1, 3, 4], 6),
          '| DP ->', dp_min_coins([1, 3, 4], 6))
    print('Viterbi 状态序列 =', path, '对数概率 =', round(score, 4))
    print('LoRA 可训练参数 =', rr * k + d * rr, '全参 =', d * k, '压缩倍数 = 256')


if __name__ == '__main__':
    _self_test()
    print('all self-tests passed')
